using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Forms;

internal static class PetBehaviorTests {
    static int checks;const BindingFlags Hidden=BindingFlags.NonPublic|BindingFlags.Instance;
    [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr w,IntPtr l);
    [DllImport("dwmapi.dll")]static extern int DwmGetWindowAttribute(IntPtr window,int attribute,out int value,int size);
    static void Need(bool condition,string error){checks++;if(!condition)throw new Exception(error);}
    static void Pump(int milliseconds){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<milliseconds){Application.DoEvents();Thread.Sleep(10);}}
    static ContextMenuStrip Menu(PetWindow pet){return (ContextMenuStrip)typeof(PetWindow).GetField("menu",Hidden).GetValue(pet);}
    public static int Run(string root,string report,bool video,string local){try{
        string state=Path.Combine(Path.GetDirectoryName(report),"behavior-state");Directory.CreateDirectory(state);var packs=PetPack.Discover(root,local??state).Where(p=>p.Available).ToArray();var source=PetPack.Discover(root,state);foreach(string directory in Directory.GetDirectories(Path.Combine(root,@"source\assets\pets")))PetPack.Read(directory,true);Need(source.Count==4&&source.Count(p=>p.Available)==2,"Gallery entries: "+String.Join(",",source.Select(p=>p.Id).ToArray()));Need(source.First(p=>p.Id=="deepseek-fat-fish").Name=="鲸鱼女仆","Requested new name not applied");
        if(video)return Video(root,report,packs.First(p=>p.Id=="deepseek-fat-fish"));
        var all=new List<string>();foreach(var pack in packs){all.Add(pack.Id);var profile=new PetBehaviorProfile{SleepSeconds=30,WhisperEnabled=false};var director=new PetAnimationDirector(pack,profile,1);var motion=new PetMotion(3);int initial=director.Row;double idle=director.Duration(initial);director.Tick(.1,motion,"thinking",false,false,false);director.Tick(.2,motion,"success",false,false,false);Need(director.Row==initial,"Task event cut a clip before completion: "+pack.Id);director.Tick(idle+.01,motion,"success",false,false,false);int start=director.Row;Need(director.Spec.work[0].Any(i=>start==(pack.Actions==null?i:9+i)),"Short task lost its start action: "+pack.Id);int generation=director.Generation;director.Tick(idle+.02,motion,"success",false,false,false);Need(director.Generation==generation,"Work clip was immediately replaced: "+pack.Id);director.Tick(idle+director.Duration(start)+.02,motion,"success",false,false,false);Need(director.Spec.work[4].Any(i=>director.Row==(pack.Actions==null?i:9+i)),"Completion action missing: "+pack.Id);director.Tick(90,motion,"idle",false,false,false);Need(director.Sleeping,"Long inactivity did not enter sleep/rest: "+pack.Id);director.Restore(91);Need(!director.Sleeping,"Restore autonomy did not wake pet: "+pack.Id);
            var prefs=new PetPreferences{Sound=false,Roaming=false,CodexOnly=true};prefs.ForPet(pack.Id).WhisperEnabled=false;var area=new Rectangle(50,70,1400,1000);
            using(var pet=new PetWindow(pack,prefs,root){SurfaceProvider=()=>new PetSurface(area,new IntPtr(11)),DismissOnOutsideClick=false}){pet.AdvanceOnce();Pump(100);var menu=Menu(pet);var desktop=menu.Items.OfType<ToolStripMenuItem>().First(v=>v.Text=="桌面操作");((ToolStripMenuItem)desktop.DropDownItems[1]).PerformClick();Need(!prefs.CodexOnly&&pet.AllowedBounds==Screen.FromPoint(Point.Round(pet.Motion.Position)).WorkingArea,"Desktop scope failed: "+pack.Id);((ToolStripMenuItem)desktop.DropDownItems[0]).PerformClick();Need(prefs.CodexOnly&&pet.AllowedBounds==area,"Codex scope failed: "+pack.Id);
                var before=pet.Bounds;var body=pet.Geometry.Sprite;pet.OpenPanel(true);for(int i=0;i<10;i++){Pump(40);Need(pet.Bounds==before&&pet.Geometry.Sprite==body&&pet.Motion.PressScale==1,"Task popup moved or resized pet: "+pack.Id);}Need(pet.Expanded&&pet.TaskPanel&&pet.PanelReveal==1,"Task panel failed to animate");pet.OpenPanel(true);Pump(370);pet.OpenPanel(false);Pump(370);Need(!pet.TaskPanel&&pet.Bounds==before,"Quota popup changed pet geometry");pet.OpenPanel(false);Pump(370);
                var actions=menu.Items.OfType<ToolStripMenuItem>().First(v=>v.Text=="手动动作");if(pack.Actions!=null){var native=actions.DropDownItems.OfType<ToolStripMenuItem>().First(v=>v.Text=="全部原始动作"||v.Text=="白龙完整动作");Need(native.DropDownItems.Count==pack.Actions.Count,"Action menu lost source actions: "+pack.Id);((ToolStripMenuItem)native.DropDownItems[native.DropDownItems.Count-1]).PerformClick();Need(pet.Motion.Row==8+pack.Actions.Count,"Native action selected wrong row");}
                pet.Motion.Interact(3,60);menu.Items.OfType<ToolStripMenuItem>().First(v=>v.Text=="恢复自主走动").PerformClick();Need(prefs.Roaming&&pet.Motion.ReactionRemaining==0&&!pet.Motion.Sliding,"Restore autonomy remains occupied: "+pack.Id);pet.Hide();
            }
            var roam=new PetMotion(7){Position=new PointF(80,70)};roam.ResumeAutonomy();int walking=0,pausing=0;for(int i=0;i<2400;i++){roam.Update(.05,new Size(200,260),new Rectangle(0,0,320,360),true,true);if(roam.Velocity==PointF.Empty)pausing++;else walking++;Need(roam.Position.X>=0&&roam.Position.Y>=0&&roam.Position.X<=120&&roam.Position.Y<=100,"Autonomy escaped bounds while Codex busy");}Need(walking>100&&walking<600&&pausing>100&&roam.CollisionCount>0,"Busy state blocks calm pause/walk/bounce cycle: "+pack.Id+" walks="+walking+" pauses="+pausing+" collisions="+roam.CollisionCount);
        }
        for(int i=0;i<6;i++){double remaining=i==5?0:100-i*20;Need(PetAnimationDirector.QuotaBand(remaining)==i,"Quota band boundary incorrect");}
        foreach(float dpi in new[]{1F,1.5F,2F}){var size=new Size((int)(1000*dpi),(int)(700*dpi));Need(WindowFrame.ResizeHit(size,new Point((int)(9*dpi),(int)(18*dpi)),dpi)==13,"Top-left corner hit band too small");Need(WindowFrame.ResizeHit(size,new Point(size.Width-(int)(18*dpi),size.Height-(int)(9*dpi)),dpi)==17,"Bottom-right corner hit band too small");Need(WindowFrame.ResizeHit(size,new Point((int)(8*dpi),size.Height/2),dpi)==10,"Side resize band too small");Need(WindowFrame.ResizeHit(size,new Point(size.Width/2,size.Height/2),dpi)==0,"Resize band swallowed normal client area");}
        using(var form=(Form)Activator.CreateInstance(typeof(Manager),Hidden,null,new object[]{false},null)){IntPtr rootHandle=form.Handle;var child=form.Controls[0];IntPtr childHandle=child.Handle;var screen=form.PointToScreen(new Point(8,18));IntPtr point=new IntPtr((screen.Y<<16)|(screen.X&0xffff));Need(SendMessage(rootHandle,0x84,IntPtr.Zero,point).ToInt32()==13,"Native form corner hit test missed widened band");Need(SendMessage(childHandle,0x84,IntPtr.Zero,point).ToInt32()==-1,"Child panel still captures the resize band");int round;if(DwmGetWindowAttribute(rootHandle,33,out round,4)==0)Need(round==2&&form.Region==null,"Windows 11 still uses a pixel-stepped region instead of native round corners");Need(!form.Visible,"Resize proof displayed manager window");}
        using(var painter=new PetPainter(root))using(var full=painter.RenderPanel(2,true,null,"","执行/命令",true,0,null,0,false,false,new PetActivity(),0))using(var sheet=new Bitmap(2240,456))using(var g=Graphics.FromImage(sheet)){var origin=new RectangleF(57,182,165,37);float previousHeight=0;int i=0;foreach(float progress in new[]{0F,.25F,.6F,1F}){var box=PetPainter.PanelShape(origin,progress);Need(box.Height>previousHeight,"Popup only fades instead of growing from capsule");previousHeight=box.Height;using(var frame=painter.MorphPanel(full,2,origin,progress))g.DrawImageUnscaled(frame,i++*560,0);}sheet.Save(Path.Combine(Path.GetDirectoryName(report),"capsule-morph-stages.png"));}
        using(var painter=new PetPainter(root)){using(var atlas=new PetAtlas(packs.First(p=>p.Id=="deepseek")))using(var sheet=new Bitmap(1120,385))using(var g=Graphics.FromImage(sheet)){for(int i=0;i<4;i++){var motion=new PetMotion(1){CollisionDirection=1,ReactionDuration=.85,ReactionRemaining=.85*(1-(i+.5)/4),Row=5};using(var frame=painter.Render(atlas,motion,false,true,null,"",0,1,null,false,0,null,0,false,1.4F))g.DrawImageUnscaled(frame,i*280,0);}sheet.Save(Path.Combine(Path.GetDirectoryName(report),"collision-recoil-stages.png"));}}
        var settings=new PetPreferences();settings.ForPet("deepseek").WhisperSeconds=90;settings.ForPet("bailong").WhisperEnabled=false;settings.Save(state);var restored=PetPreferences.Load(state);Need(restored.ForPet("deepseek").WhisperSeconds==90&&!restored.ForPet("bailong").WhisperEnabled&&restored.ForPet("xiaolemi").WhisperSeconds==600,"Per-pet independent settings lost");Need(typeof(PetWindow).Assembly.GetType("PetOfflineChat")==null,"Removed chat feature still exists");
        File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=true,checks,pets=all,completeTaskChain=true,sleepAndRandomActions=true,popupBodyStable=true,allPetScopes=true,busyAutonomy=true,whisperRemoved=true,oldResizeTestsRepeated=false}));return 0;
    }catch(Exception error){File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=false,checks,error=error.ToString()}));return 1;}}
    static int Video(string root,string report,PetPack pack){Need(pack.Actions.Count==106&&pack.Format=="transparent-video-set","Production video catalog incomplete");string decoder=Path.Combine(root,@"engine\runtime\ffmpeg\ffmpeg.exe");Need(File.Exists(decoder),"Bundled decoder missing");var samples=new[]{pack.Behavior.idle[0],pack.Behavior.work[1][0],pack.Behavior.quota[5][0]};var totals=new List<int>();foreach(int index in samples){var action=pack.Actions[index];using(var stream=new PetVideoStream(decoder,Path.Combine(pack.Directory,action.file),action.cellWidth,action.cellHeight,action.fps)){var clock=Stopwatch.StartNew();int frames=0,last=-1;bool alpha=false,visible=false;while(!stream.Ended&&clock.Elapsed.TotalSeconds<16){PetVideoStream.Frame frame;if(stream.TryFrame(clock.Elapsed.TotalSeconds,out frame)){Need(frame.Index>last,"Decoder frame order regressed");last=frame.Index;frames++;for(int p=3;p<frame.Pixels.Length;p+=4){if(frame.Pixels[p]==0)alpha=true;else if(frame.Pixels[p]>32)visible=true;}stream.Recycle(frame.Pixels);}Thread.Sleep(10);}Need(stream.Error==null,"Bundled VP9 decoder failed: "+stream.Error);Need(stream.Ended&&last>=action.frames-2&&frames>=180,"Clip was truncated or failed to play at original rate");Need(alpha&&visible,"Production alpha was lost");totals.Add(frames);}}
        using(var atlas=new PetAtlas(pack))using(var pixels=new Bitmap(640,360))using(var g=Graphics.FromImage(pixels)){atlas.BeginVideo(9+samples[0],0);var clock=Stopwatch.StartNew();for(int i=0;i<70;i++){g.Clear(Color.Transparent);atlas.Draw(g,new Rectangle(0,0,640,360),9+samples[0],clock.Elapsed.TotalSeconds);Thread.Sleep(20);}Need(atlas.VideoError==null,"Native renderer could not decode alpha video");pixels.Save(Path.Combine(Path.GetDirectoryName(report),"production-alpha.png"));int transparent=0,visible=0;for(int y=0;y<atlas.Bitmap.Height;y+=5)for(int x=0;x<atlas.Bitmap.Width;x+=5){byte a=atlas.Bitmap.GetPixel(x,y).A;if(a<8)transparent++;if(a>32)visible++;}Need(transparent>1000&&visible>100,"Native renderer flattened VP9 alpha: "+transparent+"/"+visible);}
        File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=true,checks,productionActions=106,originalFps=24,originalSize="640x360",fullClipsDecoded=samples.Length,frameCounts=totals,boundedBuffers=true,noSystemDecoderDependency=true}));return 0;
    }
}
